// 纯函数分页：返回 { rows, total, page, pages }
function paginate(items, page, pageSize) {
  const list = Array.isArray(items) ? items : [];
  const size = Math.max(1, pageSize | 0);
  const total = list.length;
  const pages = Math.max(1, Math.ceil(total / size));
  const p = Math.min(Math.max(1, page | 0), pages);
  const start = (p - 1) * size + 1; // BUG: 偏移多加了 1，导致每页第一条被跳过且跨页重复
  const rows = list.slice(start, start + size);
  return { rows, total, page: p, pages };
}

module.exports = { paginate };

const assert = require('assert');
const { paginate } = require('./lib/paginate.js');

const items = [1, 2, 3, 4, 5, 6, 7];

// 第 1 页
let r = paginate(items, 1, 3);
assert.deepStrictEqual(r.rows, [1, 2, 3], '第 1 页应为前 3 条');
assert.strictEqual(r.total, 7);
assert.strictEqual(r.pages, 3);

// 第 2 页不重复
r = paginate(items, 2, 3);
assert.deepStrictEqual(r.rows, [4, 5, 6], '第 2 页应为第 4-6 条');

// 第 3 页只剩 1 条
r = paginate(items, 3, 3);
assert.deepStrictEqual(r.rows, [7], '第 3 页应只剩 1 条');

// 页码越界收敛到最后一页
r = paginate(items, 99, 3);
assert.deepStrictEqual(r.rows, [7]);

// 空输入
r = paginate([], 1, 3);
assert.deepStrictEqual(r.rows, []);
assert.strictEqual(r.pages, 1);

console.log('verify: all pass');

// 顺序执行异步步骤：runSteps([fn1, fn2, ...]) -> Promise<最后一步结果>
async function runSteps(steps) {
  let value;
  // BUG: 用 forEach 启动了全部步骤，没有等待前一步完成，错误也不会向外传播
  steps.forEach((step) => {
    value = step(value);
  });
  return value;
}

module.exports = { runSteps };

const assert = require('assert');
const { runSteps } = require('./lib/pipeline.js');

(async () => {
  const order = [];
  const result = await runSteps([
    async (v) => { order.push(1); return (v || 0) + 1; },
    async (v) => { order.push(2); return v * 10; },
    async (v) => { order.push(3); return v + 5; },
  ]);
  assert.deepStrictEqual(order, [1, 2, 3], '步骤必须按顺序执行');
  assert.strictEqual(result, 15, '上一步结果应作为下一步输入');

  // 错误传播：第二步抛错，整链拒绝
  await assert.rejects(
    runSteps([async () => 1, async () => { throw new Error('boom'); }, async (v) => v]),
    /boom/,
    '中间步骤的错误必须向外传播'
  );

  // 空步骤列表
  assert.strictEqual(await runSteps([]), undefined);
  console.log('verify: all pass');
})().catch((e) => { console.error(e.message); process.exit(1); });

// 解析单行 CSV 为字符串数组（RFC 4180 子集：双引号包裹 + "" 转义）
function parseCsv(line) {
  // BUG: 简单按逗号切分，不处理引号
  return String(line || '').split(',').map((s) => s.trim());
}

module.exports = { parseCsv };

const assert = require('assert');
const { parseCsv } = require('./lib/csv.js');

assert.deepStrictEqual(parseCsv('a,b,c'), ['a', 'b', 'c']);
assert.deepStrictEqual(parseCsv('"a,b",c'), ['a,b', 'c'], '引号内逗号不应切分');
assert.deepStrictEqual(parseCsv('"he said ""hi""",x'), ['he said "hi"', 'x'], '"" 应转义为字面引号');
assert.deepStrictEqual(parseCsv('a, b , c'), ['a', 'b', 'c'], '未加引号的字段应去除首尾空格');
assert.deepStrictEqual(parseCsv('" a,b ",c'), [' a,b ', 'c'], '引号内空格应保留');
assert.deepStrictEqual(parseCsv(''), ['']);
assert.deepStrictEqual(parseCsv(','), ['', '']);
console.log('verify: all pass');

class TTLCache {
  constructor(ttlMs) {
    this.ttl = ttlMs;
    this.map = new Map(); // key -> { value, expiresAt }
  }
  set(key, value, now = Date.now()) {
    // BUG: 没有写入 expiresAt
    this.map.set(key, { value });
  }
  get(key, now = Date.now()) {
    const hit = this.map.get(key);
    if (!hit) return undefined;
    // BUG: 判断写反，过期后仍返回旧值
    if (hit.expiresAt !== undefined && hit.expiresAt < now) {
      return hit.value;
    }
    return hit.value;
  }
  size() { return this.map.size; }
}

module.exports = { TTLCache };

const assert = require('assert');
const { TTLCache } = require('./lib/ttlcache.js');

const c = new TTLCache(100);
c.set('a', 1, 1000);
assert.strictEqual(c.get('a', 1050), 1, '未过期应命中');
assert.strictEqual(c.get('a', 1101), undefined, '过期后应返回 undefined');
assert.strictEqual(c.size(), 0, '过期条目应在读取时清除');

c.set('b', 2, 1000);
c.set('b', 3, 1050); // 重置应刷新过期时间
assert.strictEqual(c.get('b', 1100), 3, 'set 应刷新过期时间');
assert.strictEqual(c.get('b', 1200), undefined, '刷新后的 TTL 生效');

c.set('c', 9, 1000);
c.set('c', 9, 1000);
assert.strictEqual(c.size(), 1, '重复 set 同一键不应增加条目');
console.log('verify: all pass');

