//   3) 返回的函数需保留 fn 的返回值语义：立即执行的那次返回 fn 的返回值，其余返回 undefined

function throttle(fn, wait) {
  throw new Error('not implemented');
}

module.exports = { throttle };

const assert = require('assert');
const { throttle } = require('./lib/throttle.js');

(async () => {
  let calls = 0;
  let lastArg = null;
  const t = throttle((x) => { calls += 1; lastArg = x; return calls; }, 50);

  assert.strictEqual(t(1), 1, '首次调用立即执行并返回结果');
  assert.strictEqual(t(2), undefined, '窗口内调用不执行');
  assert.strictEqual(t(3), undefined);
  assert.strictEqual(calls, 1);

  await new Promise((r) => setTimeout(r, 70));
  assert.strictEqual(calls, 2, '窗口结束后应有且仅有一次尾部执行');
  assert.strictEqual(lastArg, 3, '尾部执行应使用最后一次调用的参数');

  // this 透传
  const obj = { n: 7, t: throttle(function () { return this.n; }, 50) };
  assert.strictEqual(obj.t(), 7, 'this 应按调用方上下文透传');
  console.log('verify: all pass');
  process.exit(0);
})().catch((e) => { console.error(e.message); process.exit(1); });

