const assert = require('assert');
const { uniqueBy } = require('./lib/uniqueby.js');

const users = [{ id: 2, n: 'b' }, { id: 1, n: 'a' }, { id: 2, n: 'b2' }, { id: 3, n: 'c' }];
const out = uniqueBy(users, (u) => u.id);
assert.deepStrictEqual(out.map((u) => u.id), [2, 1, 3], '保留首次出现（稳定）');
assert.strictEqual(out[0], users[0], '元素引用保持不变（不复制）');
assert.notStrictEqual(out, users, '返回新数组');
assert.strictEqual(users.length, 4, '不修改原数组');

assert.deepStrictEqual(uniqueBy(['a', 'b', 'A'], (s) => s.toLowerCase()), ['a', 'b'], 'keyFn 自定义归一');
assert.deepStrictEqual(uniqueBy([1, undefined, 1, null, undefined], (x) => x), [1, undefined, null], 'undefined/null 参与去重');
assert.deepStrictEqual(uniqueBy([], (x) => x), []);
console.log('verify: all pass');

// 定价模块（内部存在重复的折扣逻辑，需要提取）

function calculateOrder(items, user) {
  let sum = items.reduce((a, b) => a + b, 0);
  // 重复逻辑 #1
  if (user && user.isVip) sum = sum * 0.8;
  if (sum >= 100) sum = sum - 10;
  return Math.round(sum * 100) / 100;
}

function quoteTotal(price, user) {
  let sum = price;
  // 重复逻辑 #2（与上面完全相同）
  if (user && user.isVip) sum = sum * 0.8;
  if (sum >= 100) sum = sum - 10;
  return Math.round(sum * 100) / 100;
}

module.exports = { calculateOrder, quoteTotal };

const assert = require('assert');
const fs = require('fs');
const src = fs.readFileSync('./lib/pricing.js', 'utf8');
const { calculateOrder, quoteTotal, calcDiscount } = require('./lib/pricing.js');

// 行为不变
assert.strictEqual(calculateOrder([60, 60], { isVip: true }), 86); // (120*0.8)-10
assert.strictEqual(calculateOrder([30, 30], { isVip: false }), 60);
assert.strictEqual(quoteTotal(125, { isVip: true }), 90);          // 125*0.8=100 -> 100-10
assert.strictEqual(quoteTotal(50, null), 50);

// 重构目标：calcDiscount 存在且两处重复逻辑消失
assert.strictEqual(typeof calcDiscount, 'function', '必须导出 calcDiscount');
assert.strictEqual(calcDiscount(125, { isVip: true }), 90);
assert.strictEqual(calcDiscount(80, { isVip: false }), 80);
const dupCount = (src.match(/0\.8/g) || []).length;
assert.ok(dupCount <= 1, `折扣逻辑应只存在一处，发现 ${dupCount} 处 0.8`);
assert.ok(!/sum \* 0\.8.*\n[\s\S]*sum >= 100.*sum - 10/.test(src.split('calcDiscount')[1] || ''), '折后规则应收敛到 calcDiscount 内');
console.log('verify: all pass');

const inbox = [];

function recieveMessage(msg) {
  if (msg === undefined || msg === null) throw new Error('msg required');
  const record = { id: inbox.length + 1, msg, recievedAt: Date.now() }; // 注意：字段名也要修正为 receivedAt
  inbox.push(record);
  return record;
}

function listInbox() {
  return inbox.slice();
}

module.exports = { recieveMessage, listInbox };

const assert = require('assert');
const fs = require('fs');
const src = fs.readFileSync('./lib/inbox.js', 'utf8');
const mod = require('./lib/inbox.js');

assert.ok(!src.includes('recieve'), '源文件不得再出现 recieve 拼写');
assert.strictEqual(typeof mod.receiveMessage, 'function', '新名 receiveMessage 必须导出');
assert.strictEqual(mod.receiveMessage, mod.recieveMessage, '旧名别名导出且指向同一实现（兼容旧调用）');

mod.receiveMessage('hello');
const list = mod.listInbox();
assert.strictEqual(list.length, 1);
assert.ok(list[0].receivedAt > 0, '记录字段应为 receivedAt');
assert.strictEqual(list[0].msg, 'hello');

assert.throws(() => mod.receiveMessage(null), /msg required/, '空值校验行为不变');
console.log('verify: all pass');

function formatPrice(price) {
  const n = Number(price);
  console.log('[formatPrice] called with', price); // BUG: 纯函数中的副作用，必须移除
  if (!Number.isFinite(n)) return 'N/A';
  return '¥' + n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

module.exports = { formatPrice };

const assert = require('assert');
const fs = require('fs');
const { formatPrice } = require('./lib/format.js');

// 捕获 stdout：纯函数不得产生任何输出
const origLog = console.log;
let emitted = '';
console.log = (...a) => { emitted += a.join(' '); };
let out;
try {
  out = [formatPrice(12345.6), formatPrice(0), formatPrice('abc'), formatPrice(-9.5)];
} finally {
  console.log = origLog;
}
assert.strictEqual(emitted, '', 'formatPrice 不得产生 console 输出，实际输出: ' + emitted);
assert.deepStrictEqual(out, ['¥12,345.60', '¥0.00', 'N/A', '¥-9.50'], '返回值行为不变');
assert.ok(!/console\.log/.test(fs.readFileSync('./lib/format.js', 'utf8')), '源码中不得残留 console.log');
console.log('verify: all pass');
